const dhammapadaLines = <String, String>{
  "quote-001": "Ý dẫn đầu các pháp,\nÝ làm chủ, ý tạo;\nNếu với ý ô nhiễm,\nNói lên hay hành động,\nKhổ não bước theo sau,\nNhư xe, chân vật kéo.",
  "quote-002": "Ý dẫn đầu các pháp,\nÝ làm chủ, ý tạo;\nNếu với ý thanh tịnh,\nNói lên hay hành động,\nAn lạc bước theo sau,\nNhư bóng, không rời hình.",
  "quote-003": "Nó mắng tôi, đánh tôi,\nNó thắng tôi, cướp tôi\nAi ôm hiềm hận ấy,\nHận thù không thể nguôi.",
  "quote-004": "Nó mắng tôi, đánh tôi,\nNó thắng tôi, cướp tôi\nKhông ôm hiềm hận ấy,\nHận thù được tự nguôi.",
  "quote-005": "Với hận diệt hận thù,\nÐời này không có được.\nKhông hận diệt hận thù,\nLà định luật ngàn thu.",
  "quote-006": "Và người khác không biết,\nChúng ta đây bị hại.\nChỗ ấy, ai hiểu được\nTranh luận được lắng êm.",
  "quote-007": "Ai sống nhìn tịnh tướng,\nKhông hộ trì các căn,\năn uống thiếu tiết độ,\nbiếng nhác, chẳng tinh cần.\nMa uy hiếp kẻ ấy,\nnhư cây yếu trước gió.",
  "quote-008": "Ai sống quán bất tịnh,\nKhéo hộ trì các căn,\năn uống có tiết độ,\nCó lòng tin, tinh cần,\nMa không uy hiếp được,\nNhư núi đá, trước gió.",
  "quote-009": "Ai mặc áo cà sa. [1]\ntâm chưa rời uế trược,\nkhông tự chế, không thực,\nkhông xứng áo cà sa",
  "quote-010": "Ai rời bỏ uế trược,\ngiới luật khéo nghiêm trì,\ntự chế, sống chơn thực,\nthật xứng áo cà sa.",
  "quote-011": "Không chân, tưởng chân thật,\nchân thật, thấy không chân:\nchúng không đạt chân thật,\ndo tà tư, tà hạnh.",
  "quote-012": "Chân thật, biết chân thật,\nKhông chân, biết không chân:\nchúng đạt được chân thật,\ndo chánh tư, chánh hạnh.",
  "quote-013": "Như mái nhà vụng lợp,\nMưa liền xâm nhập vào.\nCũng vậy tâm không tu,\nTham dục liền xâm nhập.",
  "quote-014": "Như ngôi nhà khéo lợp,\nMưa không xâm nhập vào.\nCũng vậy tâm khéo tu,\nTham dục không xâm nhập.",
  "quote-015": "Nay sầu, đời sau sầu,\nKẻ ác, hai đời sầu;\nNó sầu, nó ưu não,\nThấy nghiệp uế mình làm.",
  "quote-016": "Nay vui, đời sau vui,\nLàm phước, hai đời vui,\nNó vui, nó an vui,\nThấy nghiệp tịnh mình làm.",
  "quote-017": "Nay than, đời sau than,\nKẻ ác, hai đời than,\nNó than: ‘Ta làm ác’\nÐọa cõi dữ, than hơn.",
  "quote-018": "Nay sướng, đời sau sướng,\nLàm phước, hai đời sướng.\nNó sướng: ‘Ta làm thiện’,\nSanh cõi lành, sướng hơn.",
  "quote-019": "Nếu người nói nhiều kinh,\nKhông hành trì, phóng dật;\nNhư kẻ chăn bò người,\nKhông phần Sa môn hạnh.",
  "quote-021": "Không phóng dật, đường sống,\nPhóng dật là đường chết.\nKhông phóng dật, không chết,\nPhóng dật như chết rồi.",
  "quote-022": "Biết rõ sai biệt ấy,\nNgười trí không phóng dật,\nHoan hỷ, không phóng dật,\nAn vui hạnh bậc Thánh.",
  "quote-023": "Người hằng tu thiền định,\nThường kiên trì tinh tấn.\nBậc trí hưởng Niết Bàn,\nÐạt an tịnh vô thượng.",
  "quote-024": "Nỗ lực, giữ chánh niệm,\nTịnh hạnh, hành thận trọng\nTự điều, sống theo pháp,\nAi sống không phóng dật,\nTiếng lành ngày tăng trưởng.",
  "quote-025": "Nỗ lực, không phóng dật,\nTự điều, khéo chế ngự.\nBậc trí xây hòn đảo,\nNước lụt khó ngập tràn.",
  "quote-026": "Chúng ngu si, thiếu trí,\nChuyên sống đời phóng dật.\nNgười trí, không phóng dật,\nNhư giữ tài sản quý.",
  "quote-027": "Chớ sống đời phóng dật,\nChớ mê say dục lạc.\nKhông phóng dật, thiền định,\nÐạt được an lạc lớn.",
  "quote-028": "Người trí dẹp phóng dật,\nVới hạnh không phóng dật,\nLeo lầu cao trí tuệ,\nKhông sầu, nhìn khổ sầu,\nBậc trí đứng núi cao,\nNhìn kẻ ngu, đất bằng.",
  "quote-029": "Tinh cần giữa phóng dật,\nTỉnh thức giữa quần mê.\nNgười trí như ngựa phi,\nBỏ sau con ngựa hèn.",
  "quote-030": "Ðế Thích [1] không phóng dật,\nÐạt ngôi vị Thiên chủ.\nKhông phóng dật, được khen ;\nPhóng dật, thường bị trách.",
  "quote-031": "Vui thích không phóng dật,\nTỷ kheo sợ phóng dật,\nBước tới như lửa hừng,\nThiêu kiết sử lớn nhỏ.",
  "quote-033": "Tâm hoảng hốt giao động,\nKhó hộ trì, khó nhiếp,\nNgười trí làm tâm thẳng,\nNhư thợ tên, làm tên.",
  "quote-034": "Như cá quăng lên bờ,\nVất ra ngoài thủy giới;\nTâm này vùng vẫy mạnh,\nHãy đoạn thế lực Ma.",
  "quote-037": "Chạy xa, sống một mình,\nKhông thân, ẩn hang sâu [1]\nAi điều phục được tâm,\nThoát khỏi Ma trói buộc. [2]",
  "quote-038": "Ai tâm không an trú,\nKhông biết chân diệu pháp,\nTịnh tín bị rúng động,\nTrí tuệ không viên thành.",
  "quote-039": "Tâm không đầy tràn dục,\nTâm không (hận) công phá,\nÐoạn tuyệt mọi thiện ác,\nKẻ tỉnh không sợ hãi.",
  "quote-040": "Biết thân như đồ gốm,\nTrú tâm như thành trì,\nChống Ma với gươm trí ;\nGiữ chiến thắng [3] không tham [4]",
  "quote-041": "Không bao lâu thân này,\nSẽ nằm dài trên đất,\nBị vất bỏ, vô thức,\nNhư khúc cây vô dụng.",
  "quote-042": "Kẻ thù hại kẻ thù,\nOan gia hại oan gia,\nKhông bằng tâm hướng tà, [5]\nGây ác cho tự thân.",
  "quote-044": "Ai chinh phục đất này\nDạ ma, Thiên giới này?\nAi khéo giảng Pháp cú,\nNhư người khéo hái hoa?",
  "quote-045": "Hữu học chinh phục đất,\nDạ ma, Thiên giới này.\nHữu học giảng Pháp cú,\nNhư người khéo hái hoa.",
  "quote-046": "Biết thân như bọt nước,\nNgộ thân là như huyễn,\nBẻ tên hoa của ma,\nVượt tầm mắt thần chết.",
  "quote-047": "Người nhặt các loại hoa,\nÝ đắm say, tham nhiễm,\nBị thần chết mang đi,\nNhư lụt trôi làng ngủ.",
  "quote-049": "Như ong đến với hoa,\nKhông hại sắc và hương,\nChe chở hoa, lấy nhụy.\nBậc Thánh đi vào làng “.",
  "quote-050": "Không nên nhìn lỗi người,\nNgười làm hay không làm.\nNên nhìn tự chính mình.\nCó làm hay không làm.",
  "quote-051": "Như bông hoa tươi đẹp,\nCó sắc nhưng không hương.\nCũng vậy, lời khéo nói,\nKhông làm, không kết quả.",
  "quote-052": "Như bông hoa tươi đẹp,\nCó sắc lại thêm hương;\nCũng vậy, lời khéo nói,\nCó làm, có kết quả.",
  "quote-053": "Như từ một đống hoa,\nNhiều tràng hoa được làm.\nCũng vậy, thân sanh tử,\nPhải làm nhiều việc lành.",
  "quote-054": "Hương các loại hoa thơm\nKhông ngược bay chiều gió\nNhưng hương người đức hạnh\nNgược gió khắp tung bay\nChỉ có bậc chân nhân\nTỏa khắp mọi phương trời.",
  "quote-055": "Hoa chiên đàn, già la,\nHoa sen, hoa vũ quý,\nGiữa những hương hoa ấy,\nGiới hương là vô thượng.",
  "quote-056": "Ít giá trị hương này,\nHương già la, chiên đàn;\nChỉ hương người đức hạnh,\nTối thượng tỏa Thiên giới.",
  "quote-057": "Nhưng ai có giới hạnh,\nAn trú không phóng dật,\nChánh trí, chơn giải thoát,\nÁc ma không thấy đường.",
  "quote-058": "Như giữa đống rác nhớp,\nQuăng bỏ trên đường lớn,\nChỗ ấy hoa sen nở,\nThơm sạch, đẹp ý người.",
  "quote-060": "Ðêm dài cho kẻ thức,\nÐường dài cho kẻ mệt,\nLuân hồi dài, kẻ ngu,\nKhông biết chơn diệu pháp.",
  "quote-061": "Tìm không được bạn đường,\nHơn mình hay bằng mình,\nThà quyết sống một mình,\nKhông bè bạn kẻ ngu.",
  "quote-062": "Con tôi, tài sản tôi,\nNgười ngu sanh ưu não,\nTự ta, ta không có,\nCon đâu, tài sản đâu.",
  "quote-063": "Người ngu nghĩ mình ngu,\nNhờ vậy thành có trí.\nNgười ngu tưởng có trí,\nThật xứng gọi chí ngu.",
  "quote-064": "Người ngu, dầu trọn đời,\nThân cận người có trí,\nKhông biết được Chánh pháp,\nNhư muỗng với vị canh.",
  "quote-065": "Người trí, dầu một khắc,\nThân cận người có trí,\nBiết ngay chân diệu pháp,\nNhư lưỡi với vị canh.",
  "quote-066": "Người ngu si thiếu trí,\nTự ngã thành kẻ thù.\nLàm các nghiệp không thiện,\nPhải chịu quả đắng cay.",
  "quote-067": "Nghiệp làm không chánh thiện,\nLàm rồi sanh ăn năn,\nMặt nhuốm lệ, khóc than,\nLãnh chịu quả dị thục.",
  "quote-068": "Và nghiệp làm chánh thiện,\nLàm rồi không ăn năn,\nHoan hỷ, ý đẹp lòng,\nHưởng thọ quả dị thục.",
  "quote-069": "Người ngu nghĩ là ngọt,\nKhi ác chưa chín muồi;\nÁc nghiệp chín muồi rồi,\nNgười ngu chịu khổ đau.",
  "quote-070": "Tháng tháng với ngọn cỏ,\nNgười ngu có ăn uống\nKhông bằng phần mười sáu\nNgười hiểu pháp hữu vi.",
  "quote-071": "Nghiệp ác đã được làm,\nNhư sữa, không đông ngay,\nCháy ngầm theo kẻ ngu,\nNhư lửa tro che đậy.",
  "quote-072": "Tự nó chịu bất hạnh,\nKhi danh đến kẻ ngu.\nVận may bị tổn hại,\nÐầu nó bị nát tan.",
  "quote-073": "Ưa danh không tương xứng,\nMuốn ngồi trước tỷ kheo,\nƯa quyền tại tịnh xá,\nMuốn mọi người lễ kính.",
  "quote-074": "Mong cả hai tăng, tục,\nNghĩ rằng (chính ta làm).\nTrong mọi việc lớn nhỏ,\nPhải theo mệnh lệnh ta ”\nNgười ngu nghĩ như vậy\nDục và mạn tăng trưởng.",
  "quote-075": "Khác thay duyên thế lợi,\nKhác thay đường Niết Bàn.\nTỷ kheo, đệ tử Phật,\nHãy như vậy thắng tri.\nChớ ưa thích cung kính,\nHãy tu hạnh viễn ly.",
  "quote-076": "Nếu thấy bậc hiền trí,\nChỉ lỗi và khiển trách,\nNhư chỉ chỗ chôn vàng\nHãy thân cận người trí!\nThân cận người như vậy,\nChỉ tốt hơn, không xấu.",
  "quote-077": "Những người hay khuyên dạy,\nNgăn người khác làm ác,\nÐược người hiền kính yêu,\nBị người ác không thích.",
  "quote-078": "Chớ thân với bạn ác,\nChớ thân kẻ tiểu nhân.\nHãy thân người bạn lành,\nHãy thân bậc thượng nhân.",
  "quote-079": "Pháp hỷ đem an lạc,\nVới tâm tư thuần tịnh;\nNgười trí thường hoan hỷ,\nVới pháp bậc Thánh thuyết.",
  "quote-080": "Người trị thủy dẫn nước,\nKẻ làm tên nắn tên,\nNgười thợ mộc uốn gỗ,\nBậc trí nhiếp tự thân.",
  "quote-081": "Như đá tảng kiên cố,\nKhông gió nào giao động,\nCũng vậy, giữa khen chê,\nNgười trí không giao động.",
  "quote-082": "Như hồ nước sâu thẳm,\nTrong sáng, không khuấy đục,\nCũng vậy, nghe chánh pháp,\nNgười trí hưởng tịnh lạc.",
  "quote-083": "Người hiền bỏ tất cả,\nNgười lành không bàn dục,\nDầu cảm thọ lạc khổ,\nBậc trí không vui buồn.",
  "quote-084": "Không vì mình, vì người.\nKhông cầu được con cái,\nKhông tài sản quốc độ,\nKhông cầu mình thành tựu,\nVới việc làm phi pháp.\nVị ấy thật trì giới,\nCó trí tuệ, đúng pháp.",
  "quote-085": "Ít người giữa nhân loại,\nÐến được bờ bên kia\nCòn số người còn lại,\nXuôi ngược chạy bờ này.",
  "quote-086": "Những ai hành trì pháp,\nTheo chánh pháp khéo dạy,\nSẽ đến bờ bên kia,\nVượt ma lực khó thoát.",
  "quote-088": "Hãy cầu vui Niết Bàn,\nBỏ dục, không sở hữu,\nKẻ trí tự rửa sạch,\nCấu uế từ nội tâm.",
  "quote-089": "Những ai với chánh tâm,\nKhéo tu tập giác chi,\nTừ bỏ mọi ái nhiễm,\nHoan hỷ không chấp thủ.\nKhông lậu hoặc, sáng chói,\nSống tịch tịnh ở đời.",
  "quote-090": "Ðích đã đến, không sầu,\nGiải thoát ngoài tất cả,\nÐoạn trừ mọi buộc ràng,\nVị ấy không nhiệt não.",
  "quote-091": "Tự sách tấn, chánh niệm,\nKhông thích cư xá nào,\nNhư ngỗng trời rời ao,\nBỏ sau mọi trú ẩn.",
  "quote-092": "Tài sản không chất chứa,\nĂn uống biết liễu tri,\nTự tại trong hành xứ,\n“Không vô tướng, giải thoát, ”\nNhư chim giữa hư không,\nHướng chúng đi khó tìm.",
  "quote-093": "Ai lậu hoặc đoạn sạch,\nĂn uống không tham đắm,\nTự tại trong hành xứ,\n“Không, vô tướng giải thoát. ”\nNhư chim giữa hư không,\nDấu chân thật khó tìm. ",
  "quote-094": "Ai nhiếp phục các căn,\nNhư đánh xe điều ngự,\nMạn trừ, lậu hoặc dứt,\nNgười vậy, Chư Thiên mến.",
  "quote-095": "Như đất, không hiềm hận,\nNhư cột trụ, kiên trì,\nNhư hồ, không bùn nhơ,\nKhông luân hồi, vị ấy.",
  "quote-096": "Người tâm ý an tịnh,\nLời an, nghiệp cũng an,\nChánh trí, chơn giải thoát,\nTịnh lạc là vị ấy.",
  "quote-097": "Không tin, hiểu vô vi.\nNgười cắt mọi hệ lụy\nCơ hội tận, xả ly\nVị ấy thật tối thượng.",
  "quote-098": "Làng mạc hay rừng núi\nThung lũng hay đồi cao,\nLa Hán trú chỗ nào,\nÐất ấy thật khả ái “.",
  "quote-099": "Khả ái thay núi rừng,\nChỗ người phàm không ưa,\nVị ly tham ưa thích,\nVì không tìm dục lạc.",
  "quote-100": "Dầu nói ngàn ngàn lời,\nNhưng không gì lợi ích,\nTốt hơn một câu nghĩa,\nNghe xong, được tịnh lạc.",
  "quote-101": "Dầu nói ngàn câu kệ\nNhưng không gì lợi ích,\nTốt hơn nói một câu,\nNghe xong, được tịnh lạc.",
  "quote-102": "Dầu nói trăm câu kệ\nNhưng không gì lợi ích,\nTốt hơn một câu pháp,\nNghe xong, được tịnh lạc.",
  "quote-103": "Dầu tại bãi chiến trường\nThắng ngàn ngàn quân địch,\nTự thắng mình tốt hơn,\nThật chiến thắng tối thượng.",
  "quote-104": "Tự thắng, tốt đẹp hơn,\nHơn chiến thắng người khác.\nNgười khéo điều phục mình,\nThường sống tự chế ngự.",
  "quote-105": "Dầu Thiên Thần, Thát Bà,\nDầu Ma vương, Phạm Thiên\nKhông ai chiến thắng nổi,\nNgười tự thắng như vậy.",
  "quote-106": "Tháng tháng bỏ ngàn vàng,\nTế tự cả trăm năm,\nChẳng bằng trong giây lát,\nCúng dường bậc tự tu.\nCùng dường vậy tốt hơn,\nHơn trăm năm tế tự.",
  "quote-107": "Dầu trải một trăm năm,\nThờ lửa tại rừng sâu,\nChẳng bằng trong giây lát,\nCúng dường bậc tự tu.\nCúng dường vậy tốt hơn,\nHơn trăm năm tế tự.",
  "quote-108": "Suốt năm cúng tế vật,\nÐể cầu phước ở đời.\nKhông bằng một phần tư\nKính lễ bậc chánh trực.",
  "quote-109": "Thường tôn trọng, kính lễ\nBậc kỳ lão trưởng thượng,\nBốn pháp được tăng trưởng:\nThọ, sắc, lạc, sức mạnh.",
  "quote-111": "Ai sống một trăm năm,\nÁc tuệ, không thiền định.\nTốt hơn sống một ngày,\nCó tuệ, tu thiền định.",
  "quote-112": "Ai sống một trăm năm,\nLười nhác không tinh tấn,\nTốt hơn sống một ngày\nTinh tấn tận sức mình.",
  "quote-113": "Ai sống một trăm năm,\nKhông thấy pháp sinh diệt,\nTốt hơn sống một ngày,\nThấy được pháp sinh diệt.",
  "quote-114": "Ai sống một trăm năm,\nKhông thấy câu bất tử,\nTốt hơn sống một ngày,\nThấy được câu bất tử.",
  "quote-115": "Ai sống một trăm năm,\nKhông thấy pháp tối thượng,\nTốt hơn sống một ngày,\nThấy được pháp tối thượng.",
  "quote-116": "Hãy gấp làm điều lành,\nNgăn tâm làm điều ác.\nAi chậm làm việc lành,\nÝ ưa thích việc ác.",
  "quote-117": "Nếu người làm điều ác,\nChớ tiếp tục làm thêm.\nChớ ước muốn điều ác,\nChứa ác, tất chịu khổ.",
  "quote-118": "Nếu người làm điều thiện,\nNên tiếp tục làm thêm.\nHãy ước muốn điều thiện,\nChứa thiện, được an lạc.",
  "quote-119": "Người ác thấy là hiền.\nKhi ác chưa chín muồi,\nKhi ác nghiệp chín muồi,\nNgười ác mới thấy ác.",
  "quote-120": "Người hiền thấy là ác,\nKhi thiện chưa chín muồi.\nKhi thiện được chín muồi,\nNgười hiền thấy là thiện.",
  "quote-121": "Chớ chê khinh điều ác,\nCho rằng “chưa đến mình “,\nNhư nước nhỏ từng giọt,\nRồi bình cũng đầy tràn.\nNgười ngu chứa đầy ác\nDo chất chứa dần dần.",
  "quote-122": "Chớ chê khinh điều thiện\nCho rằng “Chưa đến mình, ”\nNhư nước nhỏ từng giọt,\nRồi bình cũng đầy tràn.\nNgười trí chứa đầy thiện,\nDo chất chứa dần dần.",
  "quote-123": "Ít bạn đường, nhiều tiền,\nNgười buôn tránh đường hiểm.\nMuốn sống, tránh thuốc độc,\nHãy tránh ác như vậy.",
  "quote-124": "Bàn tay không thương tích,\nCó thể cầm thuốc độc.\nKhông thương tích, tránh độc,\nKhông làm, không có ác.",
  "quote-125": "Hại người không ác tâm,\nNgười thanh tịnh, không uế,\nTội ác đến kẻ ngu,\nNhư ngược gió tung bụi.",
  "quote-126": "Một số sinh bào thai,\nKẻ ác sinh địa ngục,\nNgười thiện lên cõi trời,\nVô lậu chứng Niết Bàn.",
  "quote-127": "Không trên trời, giữa biển,\nKhông lánh vào động núi,\nKhông chỗ nào trên đời,\nTrốn được quả ác nghiệp.",
  "quote-128": "Không trên trời, giữa biển,\nKhông lánh vào động núi,\nKhông chỗ nào trên đời,\nTrốn khỏi tay thần chết.",
  "quote-129": "Mọi người sợ hình phạt,\nMọi người sợ tử vong.\nLấy mình làm ví dụ\nKhông giết, không bảo giết.",
  "quote-130": "Mọi người sợ hình phạt,\nMọi người thích sống còn;\nLấy mình làm ví dụ,\nKhông giết, không bảo giết.",
  "quote-131": "Chúng sanh cầu an lạc,\nAi dùng trượng hại người,\nÐể tìm lạc cho mình,\nÐời sau không được lạc.",
  "quote-132": "Chúng sanh cầu an lạc,\nKhông dùng trượng hại người,\nÐể tìm lạc cho mình,\nÐời sau được hưởng lạc.",
  "quote-133": "Chớ nói lời ác độc,\nNói ác, bị nói lại,\nKhổ thay lời phẩn nộ,\nÐao trượng phản chạm mình.",
  "quote-134": "Nếu tự mình yên lặng,\nNhư chiếc chuông bị bể.\nNgươi đã chứng Niết Bàn\nNgươi không còn phẩn nộ.",
  "quote-135": "Với gậy người chăn bò,\nLùa bò ra bãi cỏ;\nCũng vậy, già và chết,\nLùa người đến mạng chung.",
  "quote-136": "Người ngu làm điều ác,\nKhông ý thức việc làm.\nDo tự nghiệp, người ngu\nBị nung nấu, như lửa.",
  "quote-137": "Dùng trượng phạt không trượng,\nLàm ác người không ác.\nTrong mười loại khổ đau,\nChịu gấp một loại khổ.",
  "quote-138": "Hoặc khổ thọ khốc liệt,\nThân thể bị thương vong,\nHoặc thọ bệnh kịch liệt,\nHay loạn ý tán tâm.",
  "quote-139": "Hoặc tai họa từ vua,\nHay bị vu trọng tội;\nBà con phải ly tán,\nTài sản bị nát tan.",
  "quote-140": "Hoặc phòng ốc nhà cửa\nBị hỏa tai thiêu đốt.\nKhi thân hoại mạng chung,\nÁc tuệ sanh địa ngục.",
  "quote-141": "Không phải sống lõa thể\nBện tóc, tro trét mình,\nTuyệt thực, lăn trên đất,\nSống nhớp, siêng ngồi xổm,\nLàm con người được sạch,\nNếu không trừ nghi hoặc.",
  "quote-142": "Ai sống tự trang sức,\nNhưng an tịnh, nhiếp phục,\nSống kiên trì, phạm hạnh,\nKhông hại mọi sinh linh,\nVị ấy là phạm chí,\nHay sa môn, khất sĩ.",
  "quote-143": "Thật khó tìm ở đời,\nNgười biết thẹn, tự chế,\nBiết tránh né chỉ trích\nNhư ngựa hiền tránh roi.",
  "quote-144": "Như ngựa hiền chạm roi,\nHãy nhiệt tâm, hăng hái,\nVới tín, giới, tinh tấn,\nThiền định cùng trạch pháp.\nMinh hạnh đủ, chánh niệm,\nÐoạn khổ này vô lượng.",
  "quote-145": "Người trị thủy dẫn nước,\nKẻ làm tên nắn tên,\nNgười thợ mộc uốn ván,\nBậc tự điều, điều thân.",
  "quote-146": "Cười gì, hân hoan gì,\nKhi đời mãi bị thiêu?\nBị tối tăm bao trùm,\nSao không tìm ngọn đèn?",
  "quote-147": "Hãy xem bong bóng đẹp,\nChỗ chất chứa vết thương,\nBệnh hoạn nhiều suy tư,\nThật không gì trường cửu.",
  "quote-148": "Sắc này bị suy già,\nỔ tật bệnh, mỏng manh,\nNhóm bất tịnh, đỗ vỡ,\nChết chấm dứt mạng sống.",
  "quote-149": "Như trái bầu mù thu,\nBị vất bỏ quăng đi,\nNhóm xương trắng bồ câu,\nThấy chúng còn vui gì?",
  "quote-150": "Thành này làm bằng xương,\nQuét tô bằng thịt máu,\nỞ đây già và chết,\nMạn, lừa đảo chất chứa.",
  "quote-151": "Xe vua đẹp cũng già.\nThân này rồi sẽ già,\nPháp bậc thiện, không già.\nNhư vậy bậc chí thiện\nNói lên cho bậc thiện.",
  "quote-152": "Người ít nghe kém học,\nLớn già như trâu đực.\nThịt nó tuy lớn lên,\nNhưng tuệ không tăng trưởng.",
  "quote-153": "Lang thang bao kiếp sống\nTa tìm nhưng chẳng gặp,\nNgười xây dựng nhà này,\nKhổ thay, phải tái sanh.",
  "quote-154": "Ôi! Người làm nhà kia\nNay ta đã thấy ngươi!\nNgươi không làm nhà nữa.\nÐòn tay ngươi bị gẫy,\nKèo cột ngươi bị tan\nTâm ta đạt tịch diệt,\nTham ái thảy tiêu vong.",
  "quote-155": "Lúc trẻ, không phạm hạnh,\nKhông tìm kiếm bạc tiền.\nNhư cò già bên ao,\nỦ rũ, không tôm cá.",
  "quote-156": "Lúc trẻ không phạm hạnh,\nKhông tìm kiếm bạc tiền;\nNhư cây cung bị gẫy,\nThở than những ngày qua.",
  "quote-157": "Nếu biết yêu tự ngã,\nPhải khéo bảo vệ mình,\nNgười trí trong ba canh,\nPhải luôn luôn tỉnh thức.",
  "quote-158": "Trước hết tự đặt mình,\nVào những gì thích đáng.\nSau mới giáo hóa người,\nNgười trí khỏi bị nhiễm.",
  "quote-159": "Hãy tự làm cho mình,\nNhư điều mình dạy người.\nKhéo tự điều, điều người,\nKhó thay, tự điều phục!",
  "quote-160": "Tự mình y chỉ mình,\nNào có y chỉ khác.\nNhờ khéo điều phục mình,\nÐược y chỉ khó được.",
  "quote-161": "Ðiều ác tự mình làm,\nTự mình sanh, mình tạo.\nNghiền nát kẻ ngu si,\nNhư kim cương, ngọc báu.",
  "quote-162": "Phá giới quá trầm trọng,\nNhư dây leo bám cây\nGieo hại cho tự thân,\nNhư kẻ thù mong ước.",
  "quote-163": "Dễ làm các điều ác,\nDễ làm tự hại mình.\nCòn việc lành, việc tốt,\nThật tối thượng khó làm.",
  "quote-164": "Kẻ ngu si miệt thị,\nGiáo pháp bậc La Hán,\nBậc Thánh, bậc chánh mạng.\nChính do ác kiến này,\nNhư quả loại cây lau\nMang quả tự hoại diệt.",
  "quote-165": "Tự mình, làm điều ác,\nTự mình làm nhiễm ô,\nTự mình không làm ác,\nTự mình làm thanh tịnh.\nTịnh, không tịnh tự mình,\nKhông ai thanh tịnh ai!",
  "quote-166": "Chớ theo pháp hạ liệt.\nChớ sống mặc, buông lung;\nChớ tin theo tà kiến,\nChớ tăng trưởng tục trần.",
  "quote-168": "Nỗ lực, chớ phóng dật!\nHãy sống theo chánh hạnh;\nNgười chánh hạnh hưởng lạc,\nCả đời này, đời sau.",
  "quote-169": "Hãy khéo sống chánh hạnh,\nChớ sống theo tà hạnh!\nNgười chánh hạnh hưởng lạc,\nCả đời này, đời sau.",
  "quote-170": "Hãy nhìn như bọt nước,\nHãy nhìn như cảnh huyễn!\nQuán nhìn đời như vậy,\nThần chết không bắt gặp.",
  "quote-171": "Hãy đến nhìn đời này,\nNhư xe vua lộng lẫy,\nNgười ngu mới tham đắm,\nKẻ trí nào đắm say.",
  "quote-172": "Ai sống trước buông lung,\nSau sống không phóng dật,\nChói sáng rực đời này.\nNhư trăng thoát mây che.",
  "quote-173": "Ai dùng các hạnh lành,\nLàm xóa mờ nghiệp ác,\nChói sáng rực đời này,\nNhư trăng thoát mây che.",
  "quote-174": "Ðời này thật mù quáng,\nÍt kẻ thấy rõ ràng.\nNhư chim thoát khỏi lưới,\nRất ít đi thiên giới.",
  "quote-175": "Như chim thiên nga bay,\nThần thông liệng giữa trời;\nChiến thắng ma, ma quân,\nKẻ trí thoát đời này.",
  "quote-176": "Ai vi phạm một pháp,\nAi nói lời vọng ngữ,\nAi bác bỏ đời sau,\nKhông ác nào không làm.",
  "quote-177": "Keo kiết không sanh thiên,\nKẻ ngu ghét bố thí,\nNgười trí thích bố thí,\nÐời sau, được hưởng lạc.",
  "quote-178": "Hơn thống lãnh cõi đất,\nHơn được sanh cõi trời,\nHơn chủ trì vũ trụ,\nQuả Dự Lưu tối thắng.",
  "quote-180": "Ai giải tỏa lưới tham,\nÁi phược hết dắt dẫn,\nPhật giới rộng mênh mông,\nAi dùng chân theo dõi,\nBậc không để dấu tích?",
  "quote-181": "Người trí chuyên thiền định,\nThích an tịnh viễn ly,\nChư thiên đều ái kính,\nBậc chánh giác, chánh niệm.",
  "quote-182": "Khó thay, được làm người,\nKhó thay, được sống còn,\nKhó thay, nghe diệu pháp,\nKhó thay, Phật ra đời!",
  "quote-183": "Không làm mọi điều ác.\nThành tựu các hạnh lành,\nTâm ý giữ trong sạch,\nChính lời chư Phật dạy.",
  "quote-184": "Chư Phật thường giảng dạy;\nNhẫn, khổ hạnh tối thượng,\nNiết bàn, quả tối thượng;\nXuất gia không phá người;\nSa môn không hại người.",
  "quote-185": "Không phỉ báng, phá hoại,\nHộ trì giới căn bản,\nĂn uống có tiết độ,\nSàng tọa chỗ nhàn tịnh\nChuyên chú tăng thượng tâm,\nChính lời chư Phật dạy.",
  "quote-186": "Dầu mưa bằng tiền vàng,\nCác dục khó thỏa mãn.\nDục đắng nhiều ngọt ít,\nBiết vậy là bậc trí.",
  "quote-187": "Ðệ tử bậc chánh giác,\nKhông tìm cầu dục lạc,\nDầu là dục chư thiên,\nChỉ ưa thích ái diệt.",
  "quote-188": "Loài người sợ hoảng hốt,\nTìm nhiều chỗ quy y,\nHoặc rừng rậm, núi non,\nHoặc vườn cây, đền tháp.",
  "quote-189": "Quy y ấy không ổn,\nKhông quy y tối thượng.\nQuy y các chỗ ấy,\nKhông thoát mọi khổ đau.",
  "quote-190": "Ai quy y Ðức Phật,\nChánh pháp và chư tăng,\nAi dùng chánh tri kiến,\nThấy được bốn Thánh đế.",
  "quote-191": "Thấy khổ và khổ tập,\nThấy sự khổ vượt qua,\nThấy đường Thánh tám ngành,\nÐưa đến khổ não tận.",
  "quote-192": "Thật quy y an ổn,\nThật quy y tối thượng,\nCó quy y như vậy,\nMới thoát mọi khổ đau.",
  "quote-193": "Khó gặp bậc thánh nhơn,\nKhông phải đâu cũng có.\nChỗ nào bậc trí sanh,\nGia đình tất an lạc.",
  "quote-194": "Vui thay, Phật ra đời!\nVui thay, Pháp được giảng!\nVui thay, Tăng hòa hợp!\nHòa hợp tu, vui thay!",
  "quote-195": "Cúng dường bậc đáng cúng,\nChư Phật hoặc đệ tử,\nCác bậc vượt hý luận,\nÐoạn diệt mọi sầu bi.",
  "quote-197": "Vui thay, chúng ta sống,\nKhông hận, giữa hận thù!\nGiữa những người thù hận,\nTa sống, không hận thù!",
  "quote-198": "Vui thay, chúng ta sống,\nKhông bệnh, giữa ốm đau!\nGiữa những người bệnh hoạn,\nTa sống, không ốm đau.",
  "quote-199": "Vui thay, chúng ta sống,\nKhông rộn giữa rộn ràng;\nGiữa những người rộn ràng,\nTa sống, không rộn ràng.",
  "quote-200": "Vui thay chúng ta sống,\nKhông gì, gọi của ta.\nTa sẽ hưởng hỷ lạc,\nNhư chư thiên Quang Âm.",
  "quote-201": "Chiến thắng sinh thù oán,\nThất bại chịu khổ đau,\nSống tịch tịnh an lạc.\nBỏ sau mọi thắng bại.",
  "quote-202": "Lửa nào sánh lửa tham?\nÁc nào bằng sân hận?\nKhổ nào sánh khổ uẩn,\nLạc nào bằng tịnh lạc.",
  "quote-203": "Ðói ăn, bệnh tối thượng,\nCác hành, khổ tối thượng,\nHiểu như thực là vậy,\nNiết Bàn, lạc tối thượng.",
  "quote-204": "Không bệnh, lợi tối thượng,\nBiết đủ, tiền tối thượng,\nThành tín đối với nhau,\nLà bà con tối thượng.\nNiết Bàn, lạc tối thượng.",
  "quote-205": "Ðã nếm vị độc cư,\nÐược hưởng vị nhàn tịnh,\nKhông sợ hải, không ác,\nNếm được vị pháp hỷ.",
  "quote-206": "Lành thay, thấy thánh nhân,\nSống chung thường hưởng lạc.\nKhông thấy những người ngu,\nThường thường được an lạc.",
  "quote-207": "Sống chung với người ngu,\nLâu dài bị lo buồn.\nKhổ thay gần người ngu,\nNhư thường sống kẻ thù.\nVui thay, gần người trí,\nNhư chung sống bà con.",
  "quote-208": "Bậc hiền sĩ, trí tuệ\nBậc nghe nhiều, trì giới,\nBậc tự chế, Thánh nhân;\nHãy gần gũi, thân cận\nThiện nhân, trí giả ấy,\nNhư trăng theo đường sao.",
  "quote-209": "Tự chuyên, không đáng chuyên\nKhông chuyên, việc đáng chuyên.\nBỏ đích, theo hỷ ái,\nGanh tị bậc tự chuyên.",
  "quote-210": "Chớ gần gũi người yêu,\nTrọn đời xa kẻ ghét.\nYêu không gặp là khổ,\nOán phải gặp cũng đau.",
  "quote-211": "Do vậy chớ yêu ai,\nÁi biệt ly là ác;\nNhững ai không yêu ghét,\nKhông thể có buộc ràng.",
  "quote-212": "Do ái sinh sầu ưu,\nDo ái sinh sợ hãi,\nAi thoát khỏi tham ái,\nKhông sầu, đâu sợ hãi?",
  "quote-213": "Ái luyến sinh sầu ưu,\nÁi luyến sinh sợ hãi.\nAi giải thoát ái luyến\nKhông sầu, đâu sợ hãi?",
  "quote-214": "Hỷ ái sinh sầu ưu,\nHỷ ái sinh sợ hãi.\nAi giải thoát hỷ ái,\nKhông sầu, đâu sợ hãi?",
  "quote-215": "Dục ái sinh sầu ưu,\nDục ái sinh sợ hãi,\nAi thoát khỏi dục ái,\nKhông sầu, đâu sợ hãi?",
  "quote-216": "Tham ái sinh sầu ưu,\nTham ái sinh sợ hãi.\nAi thoát khỏi tham ái,\nKhông sầu, đâu sợ hãi.",
  "quote-217": "Ðủ giới đức, chánh kiến;\nTrú pháp, chứng chân lý,\nTự làm công việc mình,\nÐược quần chúng ái kính.",
  "quote-218": "Ước vọng pháp ly ngôn\nÝ cảm xúc thượng quả\nTâm thoát ly ác dục,\nXứng gọi bậc Thượng Lưu.",
  "quote-219": "Khách lâu ngày ly hương,\nAn toàn từ xa về,\nBà con cùng thân hữu,\nHân hoan đón chào mừng.",
  "quote-225": "Bậc hiền không hại ai,\nThân thường được chế ngự,\nÐạt được cảnh bất tử,\nÐến đây, không ưu sầu.",
  "quote-226": "Những người thường giác tỉnh,\nNgày đêm siêng tu học,\nChuyên tâm hướng Niết Bàn,\nMọi lậu hoặc được tiêu.",
  "quote-227": "A-tu-la, nên biết,\nXưa vậy, nay cũng vậy,\nNgồi im, bị người chê,\nNói nhiều bị người chê.\nNói vừa phải, bị chê.\nLàm người không bị chê,\nThật khó tìm ở đời.",
  "quote-228": "Xưa, vị lai, và nay,\nÐâu có sự kiện này,\nNgười hoàn toàn bị chê,\nNgười trọn vẹn được khen.",
  "quote-229": "Sáng sáng, thẩm xét kỹ.\nBậc có trí tán thán.\nBậc trí không tỳ vết,\nÐầy đủ giới định tuệ.",
  "quote-230": "Hạnh sáng như vàng ròng,\nAi dám chê vị ấy?\nChư thiên phải khen thưởng,\nPhạm Thiên cũng tán dương “.",
  "quote-231": "Giữ thân đừng phẫn nộ,\nPhòng thân khéo bảo vệ,\nTừ bỏ thân làm ác,\nVới thân làm hạnh lành.",
  "quote-232": "Giữ lời đừng phẫn nộ,\nPhòng lời, khéo bảo vệ,\nTừ bỏ lời thô ác,\nVới lời, nói điều lành.",
  "quote-233": "Giữ ý đừng phẫn nộ,\nPhòng ý, khéo bảo vệ,\nTừ bỏ ý nghĩ ác,\nVới ý, nghĩ hạnh lành.’",
  "quote-234": "Bậc trí bảo vệ thân,\nBảo vệ luôn lời nói\nBảo vệ cả tâm tư,\nBa nghiệp khéo bảo vệ.",
  "quote-235": "Ngươi nay giống lá héo,\nDiêm sứ đang chờ ngươi,\nNgươi đứng trước cửa chết,\nÐường trường thiếu tư lương.",
  "quote-236": "Hãy tự làm hòn đảo,\nTinh cần gấp, sáng suốt.\nTrừ cấu uế, thanh tịnh,\nÐến Thánh địa chư Thiên.",
  "quote-237": "Ðời ngươi nay sắp tàn,\nTiến gần đến Diêm Vương.\nGiữa đường không nơi nghỉ,\nÐường trường thiếu tư lương.",
  "quote-238": "Hãy tự làm hòn đảo,\nTinh cần gấp sáng suốt.\nTrừ cấu uế, thanh tịnh,\nChẳng trở lại sanh già.",
  "quote-239": "Bậc trí theo tuần tự.\nTừng sát na trừ dần.\nNhư thợ vàng lọc bụi\nTrừ cấu uế nơi mình.",
  "quote-240": "Như sét từ sắt sanh,\nSắt sanh lại ăn sắt,\nCũng vậy, quá lợi dưỡng\nTự nghiệp dẫn cõi ác.",
  "quote-241": "Không tụng làm nhớp kinh,\nKhông đứng dậy, bẩn nhà,\nBiếng nhác làm nhơ sắc,\nPhóng dật uế người canh",
  "quote-242": "Tà hạnh nhơ đàn bà,\nXan tham nhớp kẻ thí,\nÁc pháp là vết nhơ,\nÐời này và đời sau.",
  "quote-243": "Trong hàng cấu uế ấy,\nVô minh, nhơ tối thượng,\nÐoạn nhơ ấy, tỷ kheo,\nThành bậc không uế nhiễm.",
  "quote-244": "Dễ thay, sống không hổ\nSống lỗ mãng như quạ,\nSống công kích huênh hoang,\nSống liều lĩnh, nhiễm ô.",
  "quote-245": "Khó thay, sống xấu hổ,\nThường thường cầu thanh tịnh.\nSống vô tư, khiêm tốn,\nTrong sạch và sáng suốt.",
  "quote-246": "Ai ở đời sát sinh,\nNói láo không chân thật,\nỞ đời lấy không cho,\nQua lại với vợ người.",
  "quote-247": "Uống rượu men, rượu nấu,\nNgười sống đam mê vậy,\nChính ngay tại đời này,\nTự đào bới gốc mình.",
  "quote-248": "Vậy người, hãy nên biết,\nKhông chế ngự là ác.\nChớ để tham phi pháp,\nLàm người đau khổ dài.",
  "quote-249": "Do tín tâm, hỷ tâm\nLoài người mới bố thí.\nỞ đây ai bất mãn\nNgười khác được ăn uống,\nNgười ấy ngày hoặc đêm,\nKhông đạt được tâm định?",
  "quote-250": "Ai cắt được, phá được,\nTận gốc nhổ tâm ấy.\nNgười ấy ngày hoặc đêm,\nÐạt được tâm thiền định.",
  "quote-251": "Lửa nào bằng lửa tham!\nChấp nào bằng sân hận!\nLưới nào bằng lưới si!\nSông nào bằng sông ái! ",
  "quote-252": "Dễ thay thấy lỗi người,\nLỗi mình thấy mới khó.\nLỗi người ta phanh tìm,\nNhư sàng trấu trong gạo,\nCòn lỗi mình, che đậy,\nNhư kẻ gian dấu bài.",
  "quote-253": "Ai thấy lỗi của người,\nThường sanh lòng chỉ trích,\nNgười ấy lậu hoặc tăng,\nRất xa lậu hoặc diệt.",
  "quote-254": "Hư không, không dấu chân,\nNgoài đây, không sa môn,\nChúng sanh thích hý luận,\nNhư lai, hý luận trừ.",
  "quote-255": "Hư không, không dấu chân,\nNgoài đây, không sa môn.\nCác hành không thường trú,\nChư Phật không giao động.",
  "quote-256": "Ngươi đâu phải pháp trụ,\nXử sự quá chuyên chế,\nBậc trí cần phân biệt\nCả hai chánh và tà!",
  "quote-257": "Không chuyên chế, đúng pháp,\nCông bằng, dắt dẫn người,\nBậc trí sống đúng pháp,\nThật xứng danh pháp trụ.",
  "quote-258": "Không phải vì nói nhiều,\nMới xứng danh bậc trí.\nAn ổn, không oán sợ.\nThật đáng gọi bậc trí.",
  "quote-259": "Không phải vì nói nhiều,\nMới xứng danh trì pháp,\nNhững ai tuy nghe ít,\nNhưng thân hành đúng pháp,\nKhông phóng túng chánh pháp,\nMới xứng danh trì pháp.",
  "quote-260": "Không phải là trưởng lão,\nDầu cho có bạc đầu.\nNgười chỉ tuổi tác cao,\nÐược gọi là: “Lão ngu.",
  "quote-261": "Ai chân thật, đúng pháp,\nKhông hại, biết chế phục,\nBậc trí không cấu uế,\nMới xứng danh Trưởng Lão.",
  "quote-262": "Không phải nói lưu loát,\nKhông phải sắc mặt đẹp,\nThành được người lương thiện,\nNếu ganh, tham, dối trá.",
  "quote-263": "Ai cắt được, phá được\nTận gốc nhổ tâm ấy\nNgười trí ấy diệt sân,\nÐược gọi người hiền thiện.",
  "quote-264": "Ðầu trọc, không sa môn\nNếu phóng túng, nói láo.\nAi còn đầy dục tham,\nSao được gọi sa môn?",
  "quote-265": "Ai lắng dịu hoàn toàn,\nCác điều ác lớn nhỏ,\nVì lắng dịu ác pháp,\nÐược gọi là Sa môn.",
  "quote-268": "Im lặng nhưng ngu si,\nÐâu được gọi ẩn sĩ?\nNhư người cầm cán cân,\nBậc trí chọn điều lành.",
  "quote-271": "Chẳng phải chỉ giới cấm\nCũng không phải học nhiều,\nChẳng phải chứng thiền định,\nSống thanh vắng một mình.",
  "quote-272": "Ta hưởng an ổn lạc,\nPhàm phu chưa hưởng được.\nTỷ kheo, chớ tự tin\nKhi lậu hoặc chưa diệt.",
  "quote-273": "Tám chánh, đường thù thắng,\nBốn câu, lý thù thắng.\nLy tham, pháp thù thắng,\nGiữa các loài hai chân,\nPháp nhãn, người thù thắng.",
  "quote-274": "Ðường này, không đường khác\nÐưa đến kiến thanh tịnh.\nNếu ngươi theo đường này,\nMa quân sẽ mê loạn.",
  "quote-275": "Nếu người theo đường này,\nÐau khổ được đoạn tận.\nTa dạy người con đường.\nVới trí, gai chướng diệt.",
  "quote-276": "Người hãy nhiệt tình làm,\nNhư Lai chỉ thuyết dạy.\nNgười hành trì thiền định\nThoát trói buộc Ác ma.",
  "quote-277": "Tất cả hành vô thường ”\nVới Tuệ, quán thấy vậy\nÐau khổ được nhàm chán;\nChính con đường thanh tịnh.",
  "quote-278": "Tất cả hành khổ đau\nVới Tuệ quán thấy vậy,\nÐau khổ được nhàm chán;\nChính con đường thanh tịnh.",
  "quote-279": "Tất cả pháp vô ngã,\nVới Tuệ quán thấy vậy,\nÐau khổ được nhàm chán\nChính con đường thanh tịnh.",
  "quote-280": "Khi cần, không nỗ lực,\nTuy trẻ mạnh, nhưng lười\nChí nhu nhược, biếng nhác.\nVới trí tuệ thụ động,\nSao tìm được chánh đạo?",
  "quote-281": "Lời nói được thận trọng,\nTâm tư khéo hộ phòng,\nThân chớ làm điều ác,\nHãy giữ ba nghiệp tịnh,\nChứng đạo Thánh nhân dạy.",
  "quote-282": "Tu Thiền, trí tuệ sanh,\nBỏ Thiền, trí tuệ diệt.\nBiết con đường hai ngả\nÐưa đến hữu, phi hữu,\nHãy tự mình nỗ lực,\nKhiến trí tuệ tăng trưởng.",
  "quote-283": "Ðốn rừng không đốn cây\nTừ rừng, sinh sợ hãi;\nÐốn rừng (1) và ái dục,\nTỷ kheo, hãy tịch tịnh.",
  "quote-284": "Khi nào chưa cắt tiệt,\nÁi dục giữa gái trai,\nTâm ý vẫn buộc ràng,\nNhư bò con vú mẹ.",
  "quote-285": "Tự cắt dây ái dục,\nNhư tay bẻ sen thu,\nHãy tu đạo tịch tịnh,\nNiết-Bàn, Thiện Thệ dạy.",
  "quote-286": "Mùa mưa ta ở đây\nÐông, hạ cũng ở đây,\nNgười ngu tâm tưởng vậy,\nKhông tự giác hiểm nguy.",
  "quote-287": "Người tâm ý đắm say\nCon cái và súc vật,\nTử thần bắt người ấy,\nNhư lụt trôi làng ngủ. ",
  "quote-288": "Một khi tử thần đến,\nKhông có con che chở,\nKhông cha, không bà con,\nKhông thân thích che chở.",
  "quote-289": "Biết rõ ý nghĩa này,\nBậc trí lo trì giới,\nMau lẹ làm thanh tịnh,\nCon đường đến Niết-Bàn.",
  "quote-290": "Nhờ từ bỏ lạc nhỏ,\nThấy được lạc lớn hơn,\nBậc trí bỏ lạc nhỏ,\nThấy được lạc lớn hơn.",
  "quote-291": "Gieo khổ đau cho người,\nMong cầu lạc cho mình,\nBị hận thù buộc ràng\nKhông sao thoát hận thù.",
  "quote-292": "Việc đáng làm, không làm,\nKhông đáng làm, lại làm,\nNgười ngạo mạn, phóng dật,\nLậu hoặc ắt tăng trưởng.",
  "quote-293": "Người siêng năng cần mẫn,\nThường thường quán thân niệm,\nKhông làm việc không đáng,\nGắng làm việc đáng làm,\nNgười tư niệm giác tỉnh,\nLậu hoặc được tiêu trừ.",
  "quote-294": "Sau khi giết mẹ cha,\nGiết hai Vua Sát lỵ,\nGiết vương quốc, quần thần\nVô ưu, phạm chí sống.",
  "quote-295": "Sau khi giết mẹ cha,\nHai vua Bà-la-môn,\nGiết hổ tướng thứ năm\nVô ưu, phạm chí sống.",
  "quote-296": "Ðệ tử Gotama,\nLuôn luôn tự tỉnh giác\nVô luận ngày hay đêm,\nTưởng Phật Ðà thường niệm.",
  "quote-297": "Ðệ tử Gotama,\nLuôn luôn tự tỉnh giác,\nVô luận ngày hay đêm,\nTưởng Chánh Pháp thường niệm",
  "quote-298": "Ðệ tử Gotama,\nLuôn luôn tự tỉnh giác,\nVô luận ngày hay đêm,\nTưởng Tăng Già thường niệm.",
  "quote-299": "Ðệ tử Gotama,\nLuôn luôn tự tỉnh giác,\nVô luận ngày hay đêm,\nTưởng sắc thân thường niệm.",
  "quote-300": "Ðệ tử Gotama,\nLuôn luôn tự tỉnh giác,\nVô luận ngày hay đêm,\nÝ vui niềm bất hại.",
  "quote-301": "Ðệ tử Gotama,\nLuôn luôn tự tỉnh giác,\nVô luận ngày hay đêm,\nÝ vui tu thiền quán.",
  "quote-302": "Vui hạnh xuất gia khó,\nTại gia sinh hoạt khó,\nSống bạn không đồng, khổ,\nTrôi lăn luân hồi, khổ,\nVậy chớ sống luân hồi,\nChớ chạy theo đau khổ.",
  "quote-303": "Tín tâm, sống giới hạnh\nÐủ danh xưng tài sản,\nChỗ nào người ấy đến,\nChỗ ấy được cung kính.",
  "quote-304": "Người lành dầu ở xa\nSáng tỏ như núi tuyết,\nNgười ác dầu ở gần\nNhư tên bắn đêm đen.",
  "quote-305": "Ai ngồi nằm một mình.\nÐộc hành không buồn chán,\nTự điều phục một mình\nSống thoải mái rừng sâu.",
  "quote-307": "Nhiều người khoác cà sa,\nÁc hạnh không nhiếp phục.\nNgười ác, do ác hạnh,\nPhải sanh cõi Ðịa ngục.",
  "quote-308": "Tốt hơn nuốt hòn sắt\nCháy đỏ như than hồng,\nHơn ác giới, buông lung\nĂn đồ ăn quốc độ.",
  "quote-309": "Bốn nạn chờ đợi người,\nPhóng dật theo vợ người;\nMắc họa, ngủ không yên,\nBị chê là thứ ba,\nÐọa địa ngục, thứ bốn.",
  "quote-310": "Mắc họa, đọa ác thú,\nBị hoảng sợ, ít vui.\nQuốc vương phạt trọng hình.\nVậy chớ theo vợ người.",
  "quote-311": "Như cỏ sa (1) vụng nắm,\nTất bị họa đứt tay\nHạnh Sa môn tà vạy,\nTất bị đọa địa ngục.",
  "quote-312": "Sống phóng đãng buông lung,\nTheo giới cấm ô nhiễm,\nSống Phạm hạnh đáng nghi\nSao chứng được quả lớn?",
  "quote-313": "Cần phải làm, nên làm\nLàm cùng tận khả năng\nXuất gia sống phóng đãng,\nChỉ tăng loạn bụi đời.",
  "quote-314": "Ác hạnh không nên làm,\nLàm xong, chịu khổ lụy,\nThiện hạnh, ắt nên làm,\nLàm xong, không ăn năn.",
  "quote-315": "Như thành ở biên thùy,\nTrong ngoài đều phòng hộ\nCũng vậy, phòng hộ mình,\nSát na chớ buông lung.\nGiây phút qua, sầu muộn.\nKhi rơi vào địa ngục.",
  "quote-316": "Không đáng hổ, lại hổ.\nViệc đáng hổ, lại không.\nDo chấp nhận tà kiến,\nChúng sanh đi ác thú.",
  "quote-317": "Không đáng sợ, lại sợ,\nÐáng sợ, lại thấy không,\nDo chấp nhận tà kiến.\nChúng sanh đi ác thú.",
  "quote-318": "Không lỗi, lại thấy lỗi,\nCó lỗi, lại thấy không,\nDo chấp nhận tà kiến,\nChúng sanh đi ác thú.",
  "quote-319": "Có lỗi, biết có lỗi,\nKhông lỗi, biết là không,\nDo chấp nhận chánh kiến,\nChúng sanh đi cõi lành.",
  "quote-321": "Voi luyện, đưa dự hội,\nNgựa luyện, được vua cưỡi,\nNgười luyện, bậc tối thượng\nChịu đựng mọi phỉ báng.",
  "quote-322": "Tốt thay, con la thuần,\nThuần chủng loài ngựa Xinh.\nÐại tượng, voi có ngà.\nTự điều mới tối thượng.",
  "quote-333": "Vui thay, già có giới!\nVui thay, tín an trú!\nVui thay, được trí tuệ,\nVui thay, ác không làm.",
  "quote-335": "Ai sống trong đời này,\nBị ái dục buộc ràng\nSầu khổ sẽ tăng trưởng,\nNhư cỏ Bi gặp mưa.",
  "quote-336": "Ai sống trong đời này\nÁi dục được hàng phục\nSầu rơi khỏi người ấy\nNhư giọt nước lá sen.",
  "quote-337": "Ðây điều lành Ta dạy,\nCác người tụ họp đây.\nHãy nhổ tận gốc ái\nNhư nhổ gốc cỏ Bi.\nChớ để ma phá hoại,\nNhư giòng nước cỏ lau.",
  "quote-338": "Như cây bị chặt đốn,\nGốc chưa hại vẫn bền\nÁi tùy miên chưa nhổ,\nKhổ này vẫn sanh hoài.",
  "quote-339": "Ba mươi sáu dòng Ái (1),\nTrôi người đốn khả ái.\nCác tư tưởng tham ái.\nCuốn trôi người tà kiến.",
  "quote-340": "Dòng ái dục chảy khắp,\nNhư giây leo mọc tràn,\nThấy giây leo vừa sanh,\nVới tuệ, hãy đoạn gốc.",
  "quote-341": "Người đời nhớ ái dục,\nƯa thích các hỷ lạc.\nTuy mong cầu an lạc,\nHọ vẫn phải sanh già.",
  "quote-342": "Người bị ái buộc ràng,\nVùng vẫy và hoảng sợ,\nNhư thỏ bị sa lưới.\nHọ sanh ái trói buộc,\nChịu khổ đau dài dài.",
  "quote-343": "Người bị ái buộc ràng,\nVùng vẫy và hoảng sợ,\nNhư thỏ bị sa lưới.\nDo vậy vị tỷ kheo,\nMong cầu mình ly tham\nNên nhiếp phục ái dục.",
  "quote-344": "Lìa rừng lại hướng rừng (2)\nThoát rừng chạy theo rừng.\nNên xem người như vậy,\nÐược thoát khỏi buộc ràng.\nLại chạy theo ràng buộc.",
  "quote-345": "Sắt, cây, gai trói buộc\nNgười trí xem chưa bền.\nTham châu báu, trang sức\nTham vọng vợ và con.",
  "quote-346": "Người có trí nói rằng:\n“Trói buộc này thật bền.\nRì kéo xuống, lún xuống,\nNhưng thật sự khó thoát.\nNgười trí cắt trừ nó,\nBỏ dục lạc, không màng.",
  "quote-347": "Người đắm say ái dục\nTự lao mình xuống dòng\nNhư nhện sa lưới dệt.\nNgười trí cắt trừ nó,\nBỏ mọi khổ, không màng.",
  "quote-348": "Bỏ quá, hiện, vị lai,\nÐến bờ kia cuộc đời,\nÝ giải thoát tất cả,\nChớ vướng lại sanh già.",
  "quote-349": "Người tà ý nhiếp phục,\nTham sắc bén nhìn tịnh,\nNgười ấy ái tăng trưởng,\nLàm giây trói mình chặt.",
  "quote-350": "Ai vui, an tịnh ý,\nQuán bất tịnh, thường niệm,\nNgười ấy sẽ diệt ái,\nCắt đứt Ma trói buộc.",
  "quote-351": "Ai tới đích, không sợ,\nLy ái, không nhiễm ô\nNhổ mũi tên sanh tử,\nThân này thân cuối cùng.",
  "quote-352": "Ái lìa, không chấp thủ.\nCú pháp khéo biện tài\nThấu suốt từ vô ngại,\nHiểu thứ lớp trước sau.\nThân này thân cuối cùng\nVị như vậy được gọi,\nBậc Ðại trí, đại nhân.",
  "quote-353": "Ta hàng phục tất cả,\nTa rõ biết tất cả,\nKhông bị nhiễm pháp nào.\nTa từ bỏ tất cả\nÁi diệt, tự giải thoát.\nÐã tự mình thắng trí,\nTa gọi ai thầy ta?",
  "quote-354": "Pháp thí, thắng mọi thí!\nPháp vị, thắng mọi vị!\nPháp hỷ, thắng mọi hỷ!\nÁi diệt, dứt mọi khổ!",
  "quote-355": "Tài sản hại người ngu.\nKhông người tìm bờ kia\nKẻ ngu vì tham giàu,\nHại mình và hại người.",
  "quote-356": "Cỏ làm hại ruộng vườn,\nTham làm hại người đời.\nBố thí người ly tham,\nDo vậy được quả lớn.",
  "quote-357": "Cỏ làm hại ruộng vườn,\nSân làm hại người đời.\nBố thí người ly sân,\nDo vậy được quả lớn.",
  "quote-358": "Cỏ làm hại ruộng vườn,\nSi làm hại người đời,\nBố thí người ly si,\nDo vậy được quả lớn.",
  "quote-359": "Cỏ làm hại ruộng vườn,\nDục làm hại người đời.\nBố thí người ly dục,\nDo vậy được quả lớn.",
  "quote-361": "Lành thay,phòng hộ thân!\nLành thay, phòng hộ lời,\nLành thay, phòng hộ ý.\nLành thay, phòng tất cả.\nTỷ kheo phòng tất cả.\nThoát được mọi khổ đau.",
  "quote-362": "Người chế ngự tay chân,\nChế ngự lời và đầu,\nVui thích nội thiền định.\nÐộc thân, biết vừa đủ,\nThật xứng gọi tỷ kheo.",
  "quote-363": "Tỷ kheo chế ngự miệng,\nVừa lời, không cống cao,\nKhi trình bày pháp nghĩa,\nLời lẽ dịu ngọt ngào.",
  "quote-364": "Vị tỷ kheo thích Pháp,\nMến pháp, suy tư Pháp.\nTâm tư niệm chánh Pháp,\nKhông rời bỏ chánh Pháp.",
  "quote-365": "Không khinh điều mình được,\nKhông ganh người khác được\nTỷ kheo ganh tị người,\nKhông sao chứng Thiền Ðịnh.",
};
